"""Statically inspect an untrusted pickle WITHOUT executing it.

Never calls pickle.load / Unpickler.load. Instead it decodes the opcode stream
with pickletools.genops (a pure parser) and replays it on our own stack VM.
Code-execution opcodes (GLOBAL, STACK_GLOBAL, REDUCE, INST, OBJ, NEWOBJ, BUILD,
*persid*) are NEVER dispatched -- they are recorded as inert `Blocked` markers
so the surrounding legitimate data can still be recovered and audited.
"""
import sys, pickletools, pickle
from pickle import MARK, STOP, POP, POP_MARK, DUP


class Blocked:
    """Inert stand-in for a construction opcode we refuse to execute."""
    __slots__ = ("kind", "target", "args", "pos")

    def __init__(self, kind, target, args, pos):
        self.kind, self.target, self.args, self.pos = kind, target, args, pos

    def __repr__(self):
        return f"<BLOCKED {self.kind} {self.target!r} args={self.args!r} @byte {self.pos}>"


class _Mark:
    __slots__ = ()


MARKO = _Mark()


def static_load(data: bytes):
    stack, memo, blocked = [], [], []

    def pop_mark():
        i = len(stack) - 1
        while not isinstance(stack[i], _Mark):
            i -= 1
        items = stack[i + 1:]
        del stack[i:]
        return items

    def top_n(n):
        items = stack[-n:] if n else []
        del stack[len(stack) - n:]
        return items

    result = None
    for op, arg, pos in pickletools.genops(data):
        n = op.name
        # ---- construction opcodes: REFUSE, never dispatch ----
        if n in ("GLOBAL", "STACK_GLOBAL"):
            if n == "GLOBAL":
                target = arg  # "module name"
            else:
                name = stack.pop(); module = stack.pop()
                target = f"{module}.{name}"
            b = Blocked("global-lookup", target, None, pos)
            stack.append(b); blocked.append(b)
        elif n in ("REDUCE", "INST", "OBJ", "NEWOBJ", "NEWOBJ_EX"):
            args = pop_mark() if n in ("INST", "OBJ") else stack.pop()
            callable_ = stack.pop()
            b = Blocked(n, callable_, args, pos)
            stack.append(b); blocked.append(b)
        elif n == "BUILD":
            state = stack.pop()
            b = Blocked("BUILD/__setstate__", state, None, pos)
            stack.append(b); blocked.append(b)
        elif n in ("PERSID", "BINPERSID"):
            pid = arg if n == "PERSID" else stack.pop()
            b = Blocked("persistent-id", pid, None, pos)
            stack.append(b); blocked.append(b)
        # ---- safe data-construction opcodes ----
        elif n == "MARK":            stack.append(MARKO)
        elif n == "STOP":            result = stack.pop()
        elif n in ("POP",):          stack.pop()
        elif n in ("POP_MARK",):     pop_mark()
        elif n == "DUP":             stack.append(stack[-1])
        elif n == "EMPTY_DICT":      stack.append({})
        elif n == "EMPTY_LIST":      stack.append([])
        elif n == "EMPTY_SET":       stack.append(set())
        elif n == "EMPTY_TUPLE":     stack.append(())
        elif n in ("NONE", "NEWNONE"):  stack.append(None)
        elif n == "NEWTRUE":         stack.append(True)
        elif n == "NEWFALSE":        stack.append(False)
        elif n in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE",
                   "SHORT_BINSTRING", "BINSTRING", "STRING"):
            stack.append(arg)
        elif n in ("BININT", "BININT1", "BININT2", "LONG", "LONG1", "LONG4", "INT"):
            stack.append(arg)
        elif n in ("BINFLOAT", "FLOAT"):  stack.append(arg)
        elif n == "BINBYTES":        stack.append(arg)
        elif n in ("APPEND",):       stack[-1].append(stack.pop())
        elif n == "APPENDS":         tgt = stack[-1]; tgt.extend(pop_mark())
        elif n == "SETITEM":
            v = stack.pop(); k = stack.pop(); stack[-1][k] = v
        elif n == "SETITEMS":
            items = pop_mark(); d = stack[-1]
            it = iter(items)
            for k in it:
                d[k] = next(it)
        elif n in ("ADDITEMS", "SETITEMS_X"):
            items = pop_mark(); stack[-1].update(items)
        elif n in ("TUPLE", "LIST", "SET", "FROZENSET", "DICT"):
            items = pop_mark()
            if n == "TUPLE":        stack.append(tuple(items))
            elif n == "LIST":       stack.append(items)
            elif n == "SET":        stack.append(set(items))
            elif n == "FROZENSET":  stack.append(frozenset(items))
            else:
                d = {}; it = iter(items)
                for k in it:
                    d[k] = next(it)
                stack.append(d)
        elif n in ("TUPLE1", "TUPLE2", "TUPLE3"):
            stack.append(tuple(top_n(int(n[-1]))))
        elif n in ("BINGET", "LONG_BINGET", "GET"):
            stack.append(memo[arg])
        elif n == "PUT":
            memo[arg] = stack[-1]
        elif n == "MEMOIZE":
            memo[len(memo)] = stack[-1]
        elif n in ("PROTO", "FRAME", "PROTO_X"):
            pass  # framing/versioning only
        else:
            b = Blocked(f"unhandled-opcode:{n}", arg, None, pos)
            stack.append(b); blocked.append(b)

    return result, blocked


def main(path):
    with open(path, "rb") as f:
        data = f.read()
    obj, blocked = static_load(data)

    print(f"== static inspection of {path} ({len(data)} bytes) ==")
    if blocked:
        print(f"\n!! {len(blocked)} CODE-EXECUTION CONSTRUCT(S) BLOCKED (never dispatched):")
        for b in blocked:
            print(f"   byte {b.pos}: kind={b.kind} target={b.target!r}")
            if b.args is not None:
                print(f"            args={b.args!r}")
    else:
        print("\nno code-execution constructs found")

    print("\n== recovered data structure ==")
    if isinstance(obj, dict):
        for k, v in obj.items():
            if isinstance(v, dict) and len(v) > 6:
                print(f"  {k!r}: dict with {len(v)} keys -> {list(v)[:3]} ...")
            else:
                print(f"  {k!r}: {v!r}")
    else:
        print(f"  {obj!r}")
    return obj, blocked


if __name__ == "__main__":
    main(sys.argv[1] if len(sys.argv) > 1 else "incoming/model.pkl")
